"""Write the final English run record from measured artifacts and command logs."""
import json,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def probe(p):return json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-of','json',str(p)]))['format']
stats=json.loads((R/'asr-stats.json').read_text());v=probe(R/'talk.mp4');a=probe(R/'talk.m4a')
lines=['# Pipeline run — espeak-ng + whisper-cli','','Completed media and mechanical plugin run. Editorial coverage remains incomplete by design: the lead owns the draft and accepted prose. No lesson .ru.md files were edited.','','## Voice and rights','','Homebrew espeak-ng 1.52.0, `espeak-ng -v ru -s 160`. The GPL-3.0 engine is not bundled; generated speech is not covered by its licence. Text and original assets retain Apache-2.0 attribution in SOURCE.md and LICENSE.txt. No macOS System Voices are used, per lead decision concerning macOS licence §2F.','','## Environment','','MacBook Air Mac16,12, Apple M4, 10 cores (4 performance + 6 efficiency), 16 GB RAM; macOS 26.4.1 (25E253), arm64. Python 3.15.2; ffmpeg 8.1.1; Homebrew whisper-cpp 1.8.6 (whisper-cli); Node v26.9.0; Playwright 1.65.1.','','Plugin: /Users/tym83/projects/video-to-article; commit 469f2c732f27e72f1fbf50fb7468961cb83870c8; plugin source unchanged. Model: ~/whisper-models/ggml-large-v3-turbo.bin; SHA-256 1fc70f774d38eb169993ac391eea357ef47c88757ef72ee5943879b7e8e2bc69. Source commit: 1a2bbf63a0283cd6a7ab0581c43e3a663aa4e82e.','','## Result','',f"Video container: {v['duration']} seconds; {v['size']} bytes (<30 MB). Audio: {a['duration']} seconds, mono AAC at 48 kHz. Exact synthesized section sum: 1247.8102947845805 seconds (20:47.810). Video is quantized to one frame/second; slide boundaries are rounded to that grid. No speech-rate adjustment or filler silence was needed.",'',f"WER: {stats['wer']:.8%}; source {stats['source_words']} words, transcript {stats['transcript_words']} words; S={stats['substitutions']}, D={stats['deletions']}, I={stats['insertions']}. Unit-cost Levenshtein on Unicode NFC lowercase letter/digit runs, punctuation removed; ё retained; no acronym/number expansion. Punctuation-only mismatches are additional TSV rows and do not count toward WER. Timestamps identify Whisper segment starts, not word-level alignment. Category labels are heuristic.",'','transcribe-cli.py loads the unchanged plugin transcribe.py, registers a local whisper-cli backend, and invokes its main() and standard JSON/TXT/SRT writers. Word timestamps are unavailable and words arrays are empty. Whisper runs with temperature 0, no fallback and no text context; raw output and log are included. No recognition errors were manually corrected.','','chunk.py and frames.py ran against the actual media/transcript. Nine frame requests use section starts +2 seconds. coverage.py exits 2 because all 04-text editor files are absent; coverage.md is evidence of missing editorial work, not a passing factual review. proofcheck.py ran on the raw transcript without --fix; its findings are editorial hints.','','Initial sandbox Whisper attempt failed to allocate a Metal buffer (exit -11); the authorized retry with GPU access succeeded. Historical preparation/render/test attempts are retained in the log, including failures and successful retries. The initial 16 kHz AAC media was rebuilt at the brief’s 48 kHz before delivery. The two builds use identical speech PCM.','','## Reproduce','','From the repository root: run tools/build-media.py, tools/transcribe-cli.py, then the plugin chunk/frames/coverage/proofcheck commands below, tools/asr-diff.py, tools/validate-run.py, tools/write-run.py and tools/package.py (all tool paths below are explicit). Temporary section text/WAV files are recreated by build-media.py and removed after synthesis. 01-source/audio.wav is the 16 kHz ASR input and is included in the ZIP. Source and slide preparation commands are retained as historical provenance.','','Every external artifact command is logged with argv, cwd, UTC start, wall time and exit code. Nested wrapper durations overlap child durations and must not be summed. Read-only environment inspection was not timed. Report generation and packaging are timed separately in ../pipeline-run-delivery.json outside the archive, avoiding a self-referential archive log.','','## Exact commands in start order','']
for r in sorted([json.loads(s) for s in (R/'commands.jsonl').read_text().splitlines()],key=lambda r:r['start_utc']):
 lines += [f"- {r['start_utc']} | {r['wall_seconds']:.6f} s | exit {r['exit_code']}",'','```sh',r['command'],'```','']
lines+=['## Top 20 non-punctuation mismatches','','Ranked by frequency; ties retain first appearance.','','| Source | Transcript | Category | Count |','|---|---|---|---:|']
for x in stats['top_20']:lines.append(f"| {x['source'] or '∅'} | {x['transcript'] or '∅'} | {x['category']} | {x['count']} |")
lines+=['','## Inventory','','All files and exact byte sizes are listed in ../pipeline-run-inventory.tsv after packaging. ZIP includes every kit file except talk.mp4 and itself; archive integrity and each member’s bytes are checked.']
(R/'RUN.md').write_text('\n'.join(lines)+'\n')
